bookings = []

def all_bookings():
    return list(bookings)

def save(booking):
    bookings.append(booking)

cli.py:
from store import all_bookings, save

def reserve(tool, start, end):
    for b in all_bookings():
        if b["tool"] == tool and start < b["end"] and end > b["start"]:
            return False
    save({"tool": tool, "start": start, "end": end})
    return True

web.py:
from store import all_bookings, save

def reserve(request):
    tool, start, end = request["tool"], request["start"], request["end"]
    for b in all_bookings():
        if b["tool"] == tool and b["start"] <= start < b["end"]:
            return {"status": 409}
    save({"tool": tool, "start": start, "end": end})
    return {"status": 201}
